import React, { useEffect, useState } from "react";
import "./Chat.css";
import ChatRoomsAPI from "../../API/ChatRoomsAPI";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000", { transports: ["websocket"] });

function Chat(props) {
  const [activeChat, setActiveChat] = useState(false);
  const [textMessage, setTextMessage] = useState("");
  const [messages, setMessages] = useState([]);

  const onChat = () => {
    setActiveChat(!activeChat);
  };

  const onChangeText = (e) => {
    setTextMessage(e.target.value);
  };

  const handlerSend = async () => {
    if (
      localStorage.getItem("njs_asm3_roomId") &&
      textMessage.toLowerCase() === "/end"
    ) {
      await ChatRoomsAPI.addMessage({
        message: "==END ROOM==",
        roomId: localStorage.getItem("njs_asm3_roomId"),
        is_admin: false,
      });

      localStorage.removeItem("njs_asm3_roomId");
      setTextMessage("");
      setMessages([]);
      setActiveChat(false);
      return;
    }

    if (!localStorage.getItem("njs_asm3_roomId")) {
      const newRoomData = await ChatRoomsAPI.createNewRoom();
      localStorage.setItem("njs_asm3_roomId", newRoomData._id);
    }

    const data = {
      message: textMessage,
      roomId: localStorage.getItem("njs_asm3_roomId"),
      is_admin: false,
    };

    // Immediately update local messages state
    setMessages((prevMessages) => [
      ...prevMessages,
      { ...data, _id: Date.now() }, // Temporary ID for immediate display
    ]);

    try {
      await ChatRoomsAPI.addMessage(data); // Save message to database
      socket.emit("send_message", data); // Emit message to server
      setTextMessage(""); // Clear input field
    } catch (error) {
      console.error("Failed to send message:", error);
    }
  };

  const fetchData = async (roomId) => {
    if (!roomId) return;
    try {
      const response = await ChatRoomsAPI.getMessageByRoomId(roomId);
      setMessages(response.content || []);
    } catch (error) {
      console.error("Error fetching messages:", error);
    }
  };

  useEffect(() => {
    const roomId = localStorage.getItem("njs_asm3_roomId");
    if (roomId) {
      fetchData(roomId);
    }
  }, []);

  useEffect(() => {
    socket.on("receive_message", (data) => {
      console.log("Received message:", data);

      // Immediately update messages state with incoming data
      setMessages((prevMessages) => [...prevMessages, data]);

      // Optionally fetch data if you want to keep it consistent with the server
      // fetchData(data.roomId);
    });

    return () => {
      socket.off("receive_message");
    };
  }, []);

  return (
    <div className="wrapper_chat">
      <div className="chat_messenger" onClick={onChat}>
        {/* Chat icon and other UI elements */}
      </div>

      {activeChat && (
        <div className="active_chat">
          <div style={{ width: "100%" }}>
            <div className="card card-bordered">
              <div className="card-header">
                <h4 className="card-title">
                  <strong>Customer Support</strong>
                </h4>
              </div>
              <div className="ps-container">
                {messages.map((value) =>
                  !value.is_admin ? (
                    <div
                      key={value._id}
                      className="media media-chat media-chat-reverse"
                    >
                      <div className="media-body">
                        <p>You: {value.message}</p>
                      </div>
                    </div>
                  ) : (
                    <div key={value._id} className="media media-chat">
                      <img
                        className="avatar"
                        src="https://img.icons8.com/color/36/000000/administrator-male.png"
                        alt="..."
                      />
                      <div className="media-body">
                        <p>Cộng tác viên: {value.message}</p>
                      </div>
                    </div>
                  )
                )}
              </div>
              <div className="publisher bt-1 border-light">
                <input
                  type="text"
                  placeholder="Enter Message!"
                  onChange={onChangeText}
                  value={textMessage}
                  style={{ width: "80%" }}
                  onKeyPress={(e) => e.key === "Enter" && handlerSend()}
                />
                <a onClick={handlerSend} className="publisher-btn text-info">
                  <i className="fa fa-paper-plane"></i>
                </a>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default Chat;
